module counter_03 (
  input [1:0] clk,        // Clock input
  input [1:0] rst_n,      // Active low reset input
  input [1:0] en,         // Enable input
  output reg [3:0] bcd_ones, // 4-bit output for ones place BCD
  output reg [3:0] bcd_tens, // 4-bit output for tens place BCD
  output reg [1:0] carry_out // 1-bit carry out on wrap
);

  // Internal registers to hold the counter values
  reg [3:0] counter_ones;
  reg [3:0] counter_tens;

  // Always block for clocked logic
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      // Synchronous reset logic
      counter_ones <= 4'd0;
      counter_tens <= 4'd0;
      carry_out <= 1'd0;
    end else if (en) begin
      // Increment logic
      if (counter_ones == 4'd9) begin
        counter_ones <= 4'd0;
        if (counter_tens == 4'd9) begin
          counter_tens <= 4'd0;
          carry_out <= 1'd1;
        end else begin
          counter_tens <= counter_tens + 1;
          carry_out <= 1'd0;
        end
      end else begin
        counter_ones <= counter_ones + 1;
        carry_out <= 1'd0;
      end
    end else begin
      // Hold current count when not enabled
      carry_out <= 1'd0;
    end
  end

  // Assign outputs
  assign bcd_ones = counter_ones;
  assign bcd_tens = counter_tens;

endmodule

